@Component("thirdParty-handler")
@ProcessingGroup("thirdParty-processing-group")
public class ThirdPartyEventHandler {
	
	// core constructor
	ThirdPartyEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateThirdPartyEvent
     */
    @EventHandler
    public void handle( CreateThirdPartyEvent event) {
        entityManager.persist(new ThirdParty(event.getThirdPartyId(), event.getName(), event.getTaxId(), event.getAddress(), event.getSubrogations(), event.getPartyType()));
    }

    /*
     * @param	event UpdateThirdPartyEvent
     */
    @EventHandler
    public ThirdParty handle( UpdateThirdPartyEvent event) {
    	entityManager.merge(new ThirdParty(event.getThirdPartyId(), event.getName(), event.getTaxId(), event.getAddress(), event.getSubrogations(), event.getPartyType()));
    }
    
    /*
     * @param	event DeleteThirdPartyEvent
     */
    @EventHandler
    public void on( DeleteThirdPartyEvent event) {
    	ThirdParty entity = new ThirdParty();
   
    	// ------------------------------------------
    	// apply the ThirdPartyId
    	// ------------------------------------------
    	entity.setThirdPartyId( event.getThirdPartyId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ThirdPartyRepository thirdPartyEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ThirdPartyEventHandler.class.getName());

}
